// One prompt, many devices: the page. It speaks ce-wire to four cells through wire.ws-door, with one short grant:
// infer.generate@1 (the answer), place.near@1 (who answers), net.rtt@1 (this browser's round trip to each device)
// and client.gen@1 (the code panel). Every client in gen/ is generated by ce-wire-gen from the cell's own api.
import { InferGenerateClient, grantFromLink, type GenItem, type Token, type HolderInfo, type Grant } from "./gen/InferGenerate.ts";
import { PlaceNearClient, type Ranked, type Room, type Sample } from "./gen/PlaceNear.ts";
import { NetRttClient } from "./gen/NetRtt.ts";
import { ClientGenClient } from "./gen/ClientGen.ts";

const API = "infer.generate";
const $ = (s: string) => document.querySelector(s) as HTMLElement;
const esc = (s: string) => s.replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]!));
const frag = new URLSearchParams(location.hash.slice(1));
const auto = frag.get("auto") === "1";

// ---- the grant: from the link (#g=), else this page's own (GET /grant?page=inference on the door) ----
// config.json (next to the page) names the door when the page is served from another host than the door
let cfg: { wire?: string; grant?: string } = {};
let wireBase = frag.get("w") ?? `${location.protocol === "https:" ? "wss" : "ws"}://${location.host}/wire`;
let grant: Grant | null = grantFromLink();

async function pageGrant(): Promise<Grant> {
  if (grant) return grant;
  const http = wireBase.replace(/^ws/, "http").replace(/\/wire.*$/, "");
  const r = await fetch(`${frag.get("grant") ?? cfg.grant ?? http + "/grant"}?page=${encodeURIComponent(frag.get("page") ?? "inference")}`, { cache: "no-store" });
  if (!r.ok) throw new Error(`grant: ${r.status} ${(await r.text()).slice(0, 120)}`);
  const j = await r.json();
  const [k, c] = String(j.g).split(".");
  const b = (s: string) => Uint8Array.from(atob(s.replace(/-/g, "+").replace(/_/g, "/") + "===".slice((s.length + 3) % 4)), (x) => x.charCodeAt(0));
  grant = { url: wireBase, seed: b(k), chain: b(c) };
  return grant;
}

function at(g: Grant, node: string): Grant {
  if (!node || node === doorNode) return { ...g, url: wireBase };
  return { ...g, url: `${wireBase}${wireBase.includes("?") ? "&" : "?"}at=${encodeURIComponent(node)}` };
}

// ---- one kept connection per (cell, device) ----
const conns = new Map<string, Promise<any>>();
function conn<T>(key: string, make: () => Promise<T>): Promise<T> {
  let p = conns.get(key);
  if (!p) {
    p = make();
    p.catch(() => conns.delete(key));
    conns.set(key, p);
  }
  return p as Promise<T>;
}
const drop = (key: string) => conns.delete(key);
const infer = async (node: string) => conn(`ig:${node}`, async () => InferGenerateClient.connect(at(await pageGrant(), node), 6000));
const rtt = async (node: string) => conn(`rt:${node}`, async () => NetRttClient.connect(at(await pageGrant(), node), 6000));
const place = async () => conn("pn", async () => PlaceNearClient.connect(at(await pageGrant(), ""), 6000));
const gen = async () => conn("cg", async () => ClientGenClient.connect(at(await pageGrant(), ""), 6000));

// ---- devices ----
let doorNode = ""; // the node this page's door is on (16 hex)
const short = (n: string) => n.slice(0, 16);
const info = new Map<string, HolderInfo>(); // node16 -> what it last reported
const out = new Map<string, number>(); // node16 -> until (ms): withdrawn or failing, skipped
let ranked: Ranked[] = [];
let answering = "";
const COLORS = ["var(--acc)", "#4fd1c5", "#b794f4", "#f687b3", "#90cdf4"];
const colorOf = new Map<string, string>();
const color = (cls: string) => {
  if (!colorOf.has(cls)) colorOf.set(cls, COLORS[colorOf.size % COLORS.length]);
  return colorOf.get(cls)!;
};
const classOf = (node: string) => info.get(short(node))?.device_class ?? "device " + short(node).slice(0, 6);

async function ping(node: string): Promise<number | null> {
  try {
    const c = await rtt(node);
    const v: number[] = [];
    for (let i = 0; i < 3; i++) {
      const t = performance.now();
      await c.ping(BigInt(Date.now()));
      v.push(performance.now() - t);
    }
    return v.sort((a, b) => a - b)[1];
  } catch {
    drop(`rt:${node}`);
    return null;
  }
}

async function holderInfo(node: string): Promise<HolderInfo | null> {
  try {
    const h = await (await infer(node)).holder();
    info.set(short(node), h);
    return h;
  } catch {
    drop(`ig:${node}`);
    return null;
  }
}

let refreshing = false;
async function refresh() {
  if (refreshing) return;
  refreshing = true;
  try {
    const p = await place();
    const nodes = new Set<string>(ranked.map((r) => r.node));
    if (!nodes.size) {
      const first = await p.rankRoom({ api: API, major: 1, samples: [], pool: [], room: [] });
      if ("ok" in first) first.ok.forEach((r: Ranked) => nodes.add(r.node));
    }
    const samples: Sample[] = [];
    const room: Room[] = [];
    await Promise.all([...nodes].map(async (n) => {
      const [ms, h] = await Promise.all([ping(n), holderInfo(n)]);
      if (ms != null) samples.push({ node: n, rtt_ms: ms });
      if (h) room.push({ node: n, free_mem_mb: h.mem_free_mb, load1: h.load1, cores: h.cores, busy: h.busy, slots: h.slots });
    }));
    try { await (await rtt("")).report({ samples }); } catch { drop("rt:"); }
    const r = await p.rankRoom({ api: API, major: 1, samples, pool: [], room });
    if ("ok" in r) {
      // a device that left the registry is gone from the ranking; keep showing it, struck through, while it is out
      const now = Date.now();
      const kept = ranked.filter((x) => !r.ok.some((y: Ranked) => y.node === x.node) && (out.get(x.node) ?? 0) > now);
      ranked = [...r.ok, ...kept.map((x) => ({ ...x, why: "left the registry (withdrawn)", score: 0 }))];
      for (const x of r.ok) if ((out.get(x.node) ?? 0) > now && !info.get(x.node)?.withdrawn && x.why.indexOf("not reported") < 0) out.delete(x.node);
      $("#ranksrc").textContent = "place.near RankRoom, inputs: net.rtt (this browser), mesh.bench, each holder's Holder op; refreshed " + new Date().toLocaleTimeString();
    } else {
      $("#ranksrc").textContent = "place.near: " + JSON.stringify(r.err);
    }
    renderRank();
  } catch (e) {
    drop("pn");
    $("#ranksrc").textContent = "place.near unreachable: " + String(e).slice(0, 120);
  } finally {
    refreshing = false;
  }
}

function renderRank() {
  const now = Date.now();
  $("#rank").innerHTML = ranked.map((r) => {
    const h = info.get(r.node);
    const gone = (out.get(r.node) ?? 0) > now || h?.withdrawn;
    const cls = classOf(r.node);
    const cost = r.why.match(/= (\d+)$/)?.[1];
    return `<tr><td><div class="dev"><span class="sw" style="--dc:${color(cls)}"></span><span class="${gone ? "gone" : ""}">${esc(cls)}</span>${r.node === answering ? '<span class="now">answering</span>' : ""}
      <button class="btn quiet take" data-node="${r.node}" ${gone ? "disabled" : ""}>Take it away</button></div>
      <div class="why">${esc(r.why.replace(/ = \d+$/, ""))}</div><div class="sub">node ${r.node}${h ? ` · ${esc(h.model)} · ${h.tok_s ? h.tok_s.toFixed(1) + " tok/s last" : "idle"}` : ""}</div></td>
      <td class="n">${gone ? "out" : cost ? cost + " ms" : "-"}</td></tr>`;
  }).join("") || `<tr><td colspan="2">no device holds ${API} right now</td></tr>`;
}

// ---- the answer ----
const keys = new Map<string, Promise<CryptoKey>>();
const hexb = (h: string) => Uint8Array.from(h.match(/../g)!.map((x) => parseInt(x, 16)));
async function verify(t: Token): Promise<boolean> {
  try {
    if (!keys.has(t.node)) keys.set(t.node, crypto.subtle.importKey("raw", hexb(t.node), { name: "Ed25519" }, false, ["verify"]));
    const msg = new TextEncoder().encode(`infer.generate/1\n${t.req_id}\n${t.idx}\n${t.node}\n${t.device_class}\n${t.t_ms}\n${t.text}`);
    return await crypto.subtle.verify("Ed25519", await keys.get(t.node)!, hexb(t.sig), msg);
  } catch {
    return false;
  }
}

type Stats = { tokens: number; verified: number; bad: number; by: Record<string, number>; switches: { at_idx: number; from: string; to: string; gap_ms: number; moved_to_first_ms: number }[] };
let stats: Stats = { tokens: 0, verified: 0, bad: 0, by: {}, switches: [] };
let busy = false;

function best(): string | null {
  const now = Date.now();
  const r = ranked.find((x) => (out.get(x.node) ?? 0) <= now && !info.get(x.node)?.withdrawn && x.score > 0);
  return r ? r.node : null;
}

function logSwitch(html: string) {
  const li = document.createElement("li");
  li.innerHTML = `${new Date().toLocaleTimeString()} ${html}`;
  const log = $("#log");
  log.querySelector(".empty")?.remove();
  log.prepend(li);
}

async function ask(prompt: string) {
  if (busy) return;
  busy = true;
  ($("#send") as HTMLButtonElement).disabled = true;
  stats = { tokens: 0, verified: 0, bad: 0, by: {}, switches: [] };
  const ans = $("#answer");
  ans.innerHTML = "";
  const req_id = crypto.randomUUID().slice(0, 18);
  let text = "";
  let idx = 0;
  let lastTok = 0;
  let movedAt = 0;
  let from = "";
  const t0 = performance.now();
  let first = 0;
  let idxWarm = false;
  let busyWaits = 0;
  try {
    for (let hop = 0; hop < 6; hop++) {
      if (!ranked.length) await refresh();
      const node = best();
      if (!node) { $("#status").textContent = "no device can answer right now"; break; }
      answering = node;
      renderRank();
      $("#status").textContent = `asking ${classOf(node)}${idx ? `, continuing from token ${idx}` : ""}...`;
      let c: InferGenerateClient;
      try { c = await infer(node); } catch { drop(`ig:${node}`); out.set(node, Date.now() + 25000); continue; }
      const sub = c.generate({ model: "", messages: [{ role: "user", content: prompt }], max_tokens: 200, temp: 0.3, prefix: text, start_idx: idx, req_id });
      let end: "done" | "moved" | "busy" | "stop" = "stop";
      let firstHere = true;
      try {
        for (;;) {
          const it: GenItem | undefined = await sub.next(60000);
          if (!it) { end = "moved"; break; } // the stream ended without Done: the holder went away
          if (it.tag === "Token") {
            const t = it.f0;
            const now = performance.now();
            if (!first) first = now;
            if (firstHere && from && from !== node) {
              const s = { at_idx: t.idx, from: classOf(from), to: classOf(node), gap_ms: Math.round(now - lastTok), moved_to_first_ms: Math.round(now - movedAt) };
              stats.switches.push(s);
              logSwitch(`<b>switch</b> at token ${s.at_idx}: ${esc(s.from)} &rarr; ${esc(s.to)}, ${s.gap_ms} ms from the last token to the next (${s.moved_to_first_ms} ms after "moved")`);
              const cut = document.createElement("span");
              cut.className = "cut";
              cut.textContent = `→ ${s.to}`;
              ans.append(cut);
            }
            if (firstHere && !idxWarm) { idxWarm = true; warm(node, prompt, req_id); }
            firstHere = false;
            lastTok = now;
            text += t.text;
            idx = t.idx + 1;
            stats.tokens++;
            stats.by[t.device_class] = (stats.by[t.device_class] ?? 0) + 1;
            const sp = document.createElement("span");
            sp.className = "tk";
            sp.style.setProperty("--dc", color(t.device_class));
            sp.textContent = t.text;
            sp.title = `${t.device_class}\nnode ${t.node}\ntoken ${t.idx}\nsig ${t.sig.slice(0, 32)}... (checking)`;
            ans.append(sp);
            verify(t).then((ok) => {
              ok ? stats.verified++ : stats.bad++;
              sp.title = sp.title.replace("(checking)", ok ? "(signature verified)" : "(SIGNATURE DOES NOT VERIFY)");
              if (!ok) sp.classList.add("bad");
              meter();
            });
            meter();
            if (auto && autoTake && stats.tokens === autoTake) { autoTake = 0; takeAway(node); }
          } else if (it.tag === "Done") {
            end = "done";
            $("#status").textContent = `done: ${it.f0.reason}, ${it.f0.spent} tokens here at ${it.f0.tok_s.toFixed(1)} tok/s; budget left on this device: ${it.f0.budget_left < 0n ? "none set" : String(it.f0.budget_left)}`;
            break;
          } else if (it.tag === "Moved") {
            end = "moved";
            break;
          } else {
            const e = it.f0;
            if (e.tag === "NotHere") { end = "moved"; break; }
            if (e.tag === "Busy") { end = "busy"; break; }
            $("#status").textContent = `${e.tag}: ${e.f0}`;
            break;
          }
        }
      } catch (e) {
        end = "moved"; // the connection dropped: try the next device
        drop(`ig:${node}`);
      }
      if (end === "busy") {
        // every slot there is taken (for a moment, often by its own warm-up): wait and ask again
        $("#status").textContent = `${classOf(node)} is busy; asking again...`;
        await new Promise((r) => setTimeout(r, 400));
        hop--;
        if (++busyWaits > 60) break;
        continue;
      }
      if (end !== "moved") break;
      movedAt = performance.now();
      from = node;
      out.set(node, Date.now() + 25000);
      logSwitch(`${esc(classOf(node))} left after ${idx} tokens; asking the next device`);
      refresh();
    }
  } finally {
    answering = "";
    renderRank();
    busy = false;
    ($("#send") as HTMLButtonElement).disabled = false;
    (window as any).__proof = { ...stats, first_token_ms: first ? Math.round(first - t0) : null, text };
    $("#proof") && ($("#proof").textContent = JSON.stringify((window as any).__proof));
    if (auto) document.title = "DONE " + document.title;
  }
}

// The next device in the ranking reads the prompt once, in the background (one token, which it then drops), so if
// it has to take over it only reads the few tokens already written, not the whole prompt again.
async function warm(current: string, prompt: string, req_id: string) {
  const next = ranked.find((x) => x.node !== current && x.score > 0 && !info.get(x.node)?.withdrawn);
  if (!next) return;
  try {
    const s = (await infer(next.node)).generate({ model: "", messages: [{ role: "user", content: prompt }], max_tokens: 1, temp: 0.3, prefix: "", start_idx: 0, req_id: req_id + "-w" });
    while (await s.next(60000)) {}
  } catch {}
}

function meter() {
  const parts = Object.entries(stats.by).map(([k, v]) => `${k}: ${v}`);
  $("#meter").textContent = `${stats.tokens} tokens (${parts.join(", ")}); signatures verified ${stats.verified}${stats.bad ? `, FAILED ${stats.bad}` : ""}`;
  $("#legend").innerHTML = Object.keys(stats.by).map((k) => `<span><span class="sw" style="--dc:${color(k)}"></span>${esc(k)}</span>`).join("");
}

async function takeAway(node: string) {
  const cls = classOf(node);
  try {
    const r = await (await infer(node)).withdraw({ for_s: 20 });
    if ("ok" in r) {
      out.set(node, Date.now() + 21000);
      logSwitch(`<b>took away</b> ${esc(cls)}: unregistered for 20 s, ${r.ok.streams_moved} answer(s) told to move`);
    } else {
      logSwitch(`${esc(cls)} refused: ${esc(r.err.tag)} ${esc(String(r.err.f0))}`);
    }
  } catch (e) {
    logSwitch(`take away ${esc(cls)}: ${esc(String(e).slice(0, 100))}`);
  }
  refresh();
}

// ---- the code panel (client.gen) ----
async function code(lang: string) {
  document.querySelectorAll("#tabs button").forEach((b) => b.setAttribute("aria-pressed", String((b as HTMLElement).dataset.l === lang)));
  try {
    const r = await (await gen()).snippetOp({ api: API, op: "Generate", lang });
    if ("ok" in r) {
      $("#code").textContent = r.ok.lines.join("\n");
      $("#codesrc").textContent = `client.gen SnippetOp, from ${r.ok.from}; needs ${r.ok.right}`;
    } else {
      $("#code").textContent = JSON.stringify(r.err);
    }
  } catch (e) {
    drop("cg");
    $("#code").textContent = "client.gen unreachable: " + String(e).slice(0, 120);
  }
}

// ---- start ----
let autoTake = Number(frag.get("take") ?? "12");
async function start() {
  $("#tabs").innerHTML = ["ts-web", "py", "swift"].map((l) => `<button class="btn quiet" data-l="${l}">${l}</button>`).join("");
  $("#tabs").addEventListener("click", (e) => { const l = (e.target as HTMLElement).dataset.l; if (l) code(l); });
  $("#rank").addEventListener("click", (e) => { const n = (e.target as HTMLElement).dataset.node; if (n) takeAway(n); });
  $("#form").addEventListener("submit", (e) => { e.preventDefault(); ask(($("#q") as HTMLInputElement).value.trim() || "Hello"); });
  $("#theme").addEventListener("click", () => { const r = document.documentElement; r.dataset.theme = r.dataset.theme === "light" ? "dark" : "light"; });
  try {
    if (!frag.get("w")) {
      try { cfg = await (await fetch("config.json", { cache: "no-store" })).json(); } catch {}
      if (cfg.wire) wireBase = cfg.wire;
    }
    await pageGrant();
    const here = await (await rtt("")).here();
    doorNode = short(here.node);
    $("#status").textContent = "connected. Ranking devices...";
  } catch (e) {
    // no live door from here (yet): show the recorded run, so the page still shows what happens
    $("#status").textContent = "The live devices are not reachable from here right now. Below: a recorded run (2026-11-15), the same page against two devices.";
    $("#answer").innerHTML = '<img src="runs/2026-11-15.png" alt="Recorded run: 12 tokens from the ARM server, then the x86 VM continues the answer after the ARM server was taken away; 98 of 98 signatures verified" style="width:100%;height:auto;border:1px solid var(--line)">';
    $("#meter").textContent = "Recorded: 98 tokens (ARM server 12, x86 VM 86), 98 signatures verified; switch at token 12 in 3.3 s.";
    return;
  }
  code("ts-web");
  await refresh();
  $("#status").textContent = ranked.length ? `${ranked.length} devices hold ${API}. Type a prompt.` : `no device holds ${API} right now`;
  setInterval(refresh, 3000);
  if (auto) setTimeout(() => ask(($("#q") as HTMLInputElement).value), 1500);
}
start();
